function cross(a,b){
  if(!Array.isArray(a)||!Array.isArray(b)||a.length<3||b.length<3) return {error:'需三维向量'};
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]; }
function magnitude(v){ if(!Array.isArray(v)) return {error:'需向量'}; var s=0; for(var i=0;i<v.length;i++) s+=v[i]*v[i]; return Math.sqrt(s); }
var EXPORTS={cross:cross, magnitude:magnitude};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CrossForgePure = EXPORTS; }
